13 static func load_file(path: String, configuration: Dictionary, preserve_water_retention: bool=false) -> Dictionary:
14 	var file:=FileAccess.open(path,FileAccess.READ)
15 	if file==null:return {"error":&"open_failed"}
16 	if file.get_length()<48:return {"error":&"invalid_file_size"}
17 	var magic:=file.get_buffer(8).get_string_from_ascii();file.close()
18 	if magic in [Codec.MAGIC,Codec.WET_MAGIC]:
19 		var loaded:=Codec.read_container(path)
20 		if not loaded.error.is_empty():return loaded
21 		if preserve_water_retention:
22 			if not loaded.checkpoint.get("configuration") is Dictionary or not loaded.checkpoint.configuration.get("environment") is Dictionary:return {"error":&"invalid_configuration"}

